{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C64"],
      "claim": "Amphotericin B, a complex polyene macrolide natural product, has negligible oral bioavailability after oral administration due to poor membrane permeability, low aqueous solubility, and instability at low pH; this directly supports a low F prediction for the query, which is also a complex lipophilic polycyclic natural product with likely similar absorption barriers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Tacrolimus, a macrocyclic natural product, shows low and variable absolute oral bioavailability (14±5% in healthy volunteers), attributed to efflux and first-pass metabolism; this supports a low F prediction for the query, which shares a complex polycyclic scaffold and likely similar absorption/metabolic liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Isosorbide 5-mononitrate, a small polar nitrate ester, has essentially complete oral bioavailability (100%), but its small size, high aqueous solubility, and lack of a complex ring system make it poorly transferable to the query's large, lipophilic, poorly soluble polycyclic lactone; thus it does not outweigh the low-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a complex lipophilic polycyclic diterpenoid lactone (triptolide-like) with poor aqueous solubility and likely extensive first-pass metabolism. The highest-transfer evidence (amphotericin B, negligible F) and the structurally relevant macrocyclic natural product tacrolimus (14-19% F) support low oral bioavailability. Numerous high-F records come from smaller, more permeable drugs and are less transferable to this scaffold, so the low-F prediction is favored.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself; reliance on analogical evidence.",
    "The high-F evidence from small drugs may not capture the query's solubility/efflux limitations.",
    "Tacrolimus values straddle the 20% threshold, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

